-- 0037: Pilates en casa 30 días con Coach Platanita. El primer programa en días (no en semanas completas): 4 semanas de
-- 5 sesiones y un cierre en los días 29 y 30. Mientras está activo, la coach es Coach Platanita (experience.coach):
-- ella da la bienvenida, los consejos, responde en el chat y aparece haciendo cada ejercicio. También acompaña Banana Girl.
-- Portada nueva "lila". Requiere 0024 y 0027. Idempotente: se puede correr más de una vez.

-- ───────────── 1. Portada "lila" ─────────────
do $$ begin
  alter table public.challenges_catalog drop constraint if exists challenges_catalog_store_check;
  alter table public.challenges_catalog add constraint challenges_catalog_store_check check (
    status in ('borrador','publicado','oculto','archivado')
    and price_usd >= 0 and price_usd <= 200 and (price_usd = 0 or price_usd >= 0.5)
    and difficulty in ('facil','media','dificil')
    and minutes between 1 and 240
    and cover in ('banana','ember','sky','peel','noche','selva','fresa','lila')
    and (verify is null or verify in ('manual','workout','steps','protein','water'))
    and (grace is null or grace between 0 and 60)
    and (xp is null or xp between 0 and 400)
    and (steps_goal is null or steps_goal between 1000 and 50000)
    and start_mode in ('libre','fecha') and (start_mode = 'libre' or start_date is not null)
    and (onvo_price_id is null or char_length(onvo_price_id) <= 80)
    and (badge is null or char_length(badge) <= 60)
    and (reward_title is null or char_length(reward_title) <= 40)
    and (icon is null or char_length(icon) <= 24)
    and (safety_note is null or char_length(safety_note) <= 600)
  );
end $$;

-- ───────────── 2. Programas que duran días exactos ─────────────
-- program.days (opcional): duración en días cuando la última semana no es completa. Entre (semanas - 1) x 7 + 1 y
-- semanas x 7; si falta o no cuadra, dura semanas x 7 como antes.
create or replace function public._program_days(p_program jsonb)
returns int language sql immutable as $$
  select case
    when coalesce(p_program->>'days', '') ~ '^\d{1,3}$'
     and (p_program->>'days')::int > (public._program_weeks(p_program) - 1) * 7
     and (p_program->>'days')::int < public._program_weeks(p_program) * 7
    then (p_program->>'days')::int
    else public._program_weeks(p_program) * 7
  end;
$$;

/**
 * Cierra el programa y da el certificado. Solo si terminó su calendario (sus días, sin contar pausas) o si ya
 * hiciste todas las sesiones obligatorias (entrenos con la plantilla p:<slug>:<semana>.<día> desde el inicio).
 */
create or replace function public.program_finish(p_slug text, p_day date)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); cur public.user_programs%rowtype; v_prog jsonb; v_weeks int; v_days int; v_req int; v_done int;
begin
  if v_uid is null then raise exception 'No autorizado' using errcode = '42501'; end if;
  if p_day is null or not public._is_today_somewhere(p_day) then raise exception 'Fecha inválida' using errcode = '22023'; end if;
  select * into cur from public.user_programs where user_id = v_uid and slug = p_slug and status = 'activo';
  if cur.id is null then raise exception 'No tienes este programa activo' using errcode = 'P0001'; end if;
  select program into v_prog from public.challenges_catalog where slug = p_slug;
  v_weeks := public._program_weeks(v_prog);
  v_days := public._program_days(v_prog);
  if (p_day - cur.started_on) - cur.paused_days < v_days then
    with ph as (
      select ord::int as idx, sum(greatest(1, (p->>'weeks')::int)) over (order by ord) as last_week
        from jsonb_array_elements(coalesce(v_prog->'phases', '[]'::jsonb)) with ordinality as t(p, ord)
       where (p->>'weeks') ~ '^\d+$'
    ), wk as (
      select g as week, coalesce((select min(idx) from ph where ph.last_week >= g), (select max(idx) from ph)) as phase from generate_series(1, v_weeks) g
    ), req as (
      select wk.week, s.day from wk join public.program_sessions s on s.slug = p_slug and s.phase = wk.phase and not s.optional
    ), done as (
      select distinct (m)[1]::int as week, (m)[2]::int as day
        from (select regexp_match(w.template, ':(\d{1,2})\.(\d)$') as m from public.workouts w
               where w.user_id = v_uid and w.day >= cur.started_on and w.template like 'p:' || p_slug || ':%') x
       where m is not null
    )
    select count(*), count(*) filter (where exists (select 1 from done d where d.week = req.week and d.day = req.day)) into v_req, v_done from req;
    if v_req = 0 or v_done < v_req then raise exception 'Todavía no terminas el programa' using errcode = 'P0001'; end if;
  end if;
  update public.user_programs set status = 'completado', completed_at = now(), paused_on = null, updated_at = now() where id = cur.id;
  return true;
end $$;
revoke execute on function public.program_finish(text, date) from public, anon;
grant execute on function public.program_finish(text, date) to authenticated;

