-- Coach Platanita también acompaña Banana Girl (solo si su experiencia todavía no eligió coach).
update public.challenges_catalog set program = jsonb_set(program, '{experience,coach}', '"platanita"'::jsonb) where slug = 'banana-girl' and kind = 'programa' and program ? 'experience' and not (program->'experience' ? 'coach');
